let favorites = JSON.parse(localStorage.getItem("shivkali_favs") || "[]");
let currentTheme = localStorage.getItem("shivkali_theme") || "dark";

function applyTheme(theme = currentTheme) {
  currentTheme = theme === "light" ? "light" : "dark";
  document.documentElement.dataset.theme = currentTheme;
  document.body.dataset.theme = currentTheme;
  document.body.classList.toggle("theme-light", currentTheme === "light");
  localStorage.setItem("shivkali_theme", currentTheme);
  if (navTheme) {
    navTheme.classList.toggle("theme-on", currentTheme === "light");
    navTheme.setAttribute("aria-pressed", currentTheme === "light" ? "true" : "false");
    navTheme.title = currentTheme === "light" ? "Dark theme" : "Light theme";
    const label = navTheme.querySelector("span");
    if (label) label.textContent = currentTheme === "light" ? "Dark" : "Theme";
  }
}

function toggleTheme() {
  applyTheme(currentTheme === "light" ? "dark" : "light");
}

function toggleFavorite(id) {
  if (favorites.includes(id)) {
    favorites = favorites.filter(fav => fav !== id);
    if (btnFav) btnFav.classList.remove("active");
  } else {
    favorites.push(id);
    if (btnFav) btnFav.classList.add("active");
    if (window.navigator.vibrate) window.navigator.vibrate(30);
  }
  localStorage.setItem("shivkali_favs", JSON.stringify(favorites));
  updateFavoritesCategory();
}

function updateFavoritesCategory() {
  const favCat = categoryMap.find(c => c.id === "favorites");
  if (favCat) favCat.sections = favorites;
}

function updateFavButton(id) {
  if (btnFav) {
    if (favorites.includes(id)) btnFav.classList.add("active");
    else btnFav.classList.remove("active");
  }
}

updateFavoritesCategory();
applyTheme(currentTheme);

let currentQuery = "";
