function cleanTitle(title = "") {
  return title.replace(/^[^\p{L}\p{N}]+/u, "").replace(/\s*\([^)]*\)\s*/g, " ").replace(/\s+/g, " ").trim();
}

function displayTitle(title = "") {
  return cleanTitle(String(title || "").replace(/^[\s•\-–—*]+/, ""));
}

function leadingSymbol(text = "") {
  const value = String(text || "").trim();
  const match = value.match(/^[^\p{L}\p{N}<]+/u);
  return match ? match[0].trim() : "";
}

function cleanItemText(text = "") {
  return String(text || "").replace(/^[^\p{L}\p{N}<]+/u, "").trim();
}

