function getIconHtml(icon) {
  if (!icon) return "";
  if (topicIconClassMap[icon]) return iconHtmlByClass(topicIconClassMap[icon]);
  if (icon.toString().startsWith("ri-")) return iconHtmlByClass(icon);

  // Robust mapping
  const cleanIcon = icon.toString().replace(/\uFE0F/g, "").trim();
  const className = iconMap[cleanIcon] || iconMap[icon];

  if (className) {
    return `<i class="${className} ri-icon"></i>`;
  }

  return iconHtmlByClass(topicIconClassMap.default);
}

