function renderCategoryPanel(cat) {
  if (cat.id === "favorites" && cat.sections.length === 0) return "";
  const links = cat.sections.map(id => {
    const s = sectionById(id);
    return s ? `<li><button class="category-link category-topic" data-section="${s.id}">${iconHtmlByClass(topicIconClass(s), "topic-icon")}<span>${displayTitle(s.title)}</span></button></li>` : "";
  }).join("");
  return `<article class="detail-panel"><h3 class="panel-title">${getIconHtml(cat.id)}<span>${displayTitle(cat.title)}</span></h3><ul class="info-body">${links}</ul></article>`;
}

let japaCount = 0;
let malaCount = 0;
function initJapaCounter() {
  const display = document.querySelector("#japaCountDisplay");
  const malaDisplay = document.querySelector("#malaCountDisplay");
  const tapZone = document.querySelector("#btnJapaTap");
  const resetBtn = document.querySelector("#btnJapaReset");

  if (!tapZone) return;

  const update = () => {
    const fmt = (n) => String(n).padStart(3, '0');
    display.textContent = fmt(japaCount);
    malaDisplay.textContent = String(malaCount).padStart(2, '0');
  };

  tapZone.onclick = () => {
    const ctx = getAudioContext();
    if (ctx && ctx.state === 'suspended') ctx.resume();
    japaCount++;
    playJapaSound();
    if (japaCount >= 108) {
      japaCount = 0;
      malaCount++;
      if (window.navigator.vibrate) window.navigator.vibrate([100, 50, 100]); // Strong vibration for Mala
    } else {
      if (window.navigator.vibrate) window.navigator.vibrate(50); // Single solid vibration per tap
    }
    update();
  };

  resetBtn.onclick = () => {
    if (confirm("क्या आप गिनती शून्य (0) करना चाहते हैं?")) {
      japaCount = 0;
      malaCount = 0;
      update();
    }
  };
}

window.showSection = async function(id) {
  if (id === "setup-morning-notif") return scheduleNotification("सुबह की आरती", "मैया की दिव्य आरती का समय हो गया है। जय माता दी! 🚩", 6, 30);
  if (id === "setup-evening-notif") return scheduleNotification("संध्या आरती", "मैया की संध्या आरती का पावन समय हो गया है। 🔱", 19, 15);

  const s = sectionById(id);
  if (!s) return;

  updateFavButton(id);
  if (btnFav) btnFav.onclick = () => toggleFavorite(id);

  // Clean up previous tones
  detailView.className = "view active";
  if (s.tone) detailView.classList.add(`tone-${s.tone}`);

  if (s.category) {
    detailNumber.textContent = s.category;
    detailNumber.style.display = "block";
  } else {
    detailNumber.style.display = "none";
  }

  detailTitle.textContent = displayTitle(s.title || "");

  const intro = introForSection(s);
  if (intro) {
    detailIntro.textContent = intro;
    detailIntro.style.display = "block";
  } else {
    detailIntro.style.display = "none";
  }

  currentSectionId = id;
    detailContent.innerHTML = (s.blocks || []).map(renderBlock).join("");

  if (id === "japa-counter") initJapaCounter();
  if (id === "panchang") initPanchang();

  homeView.classList.remove("active");
  detailView.classList.add("active");
  quickButtons.forEach(b => b.classList.remove("active"));
  if (!isRestoringHistory) updateHistory({ view: "section", sectionId: id });

  // Ensure we are at the top of the content
  window.scrollTo({ top: 0, behavior: 'instant' });
};


function renderMenu() {
  const q = (currentQuery || "").toLowerCase().trim();
  const words = q.split(/\s+/).filter(w => w.length > 0);

  let filtered;
  if (words.length === 0) {
    const mainIds = ["mandir", "kali-upasana", "shiv-upasana", "das-mahavidya", "yogini", "nitya-puja", "sadhana", "stotra-aarti", "about-us", "donation", "agami-karyakram", "gallery"];
    filtered = mainIds.map(id => sectionsMap.get(id)).filter(Boolean);
  } else {
    filtered = sections.filter(s => {
      const idMatch = s.id.toLowerCase().includes(words[0]);
      const titleMatch = s.title.toLowerCase().includes(words[0]);

      if (words.length === 1 && (titleMatch || idMatch)) return true;

      const blockText = (s.blocks || []).map(b => {
        const itemsText = (b.items || []).map(i => typeof i === 'string' ? i : (i.text || "")).join(" ");
        return (b.title || "") + " " + (b.text || "") + " " + itemsText;
      }).join(" ");

      const fullText = `${s.title} ${s.keywords || ""} ${s.desc || ""} ${s.category || ""} ${s.intro || ""} ${blockText}`.toLowerCase();
      return words.every(word => fullText.includes(word));
    });
  }

  if (menuGrid) {
    const fragment = document.createDocumentFragment();
    if (filtered.length) {
      filtered.forEach(s => {
        const temp = document.createElement('div');
        temp.innerHTML = renderTile(s);
        fragment.appendChild(temp.firstElementChild);
      });
      menuGrid.innerHTML = "";
      menuGrid.appendChild(fragment);
    } else {
      menuGrid.innerHTML = `<p class="empty-state">कोई परिणाम नहीं मिला।</p>`;
    }
  }
}

function renderTile(s) {
  const icon = s.icon ? `assets/${s.icon}` : `assets/shivakali-hero.png`;
  return `
    <button class="menu-tile" data-section="${s.id}">
      <span class="thumb">
        <img src="${icon}" onerror="this.src='assets/shivakali-hero.png'">
      </span>
      <span class="tile-copy">
        <span class="menu-title">${displayTitle(s.title)}</span>
      </span>
    </button>`;
}

function blockIconClass(block = {}) {
  const title = displayTitle(block.title || "").toLowerCase();
  if (block.type === "panchang-live" || title.includes("पंचांग")) return topicIconClassMap.panchang;
  if (block.type === "counter") return topicIconClassMap.japa;
  if (title.includes("आरती") || title.includes("दीप")) return topicIconClassMap.aarti;
  if (title.includes("कवच") || title.includes("रक्षा")) return topicIconClassMap.kavach;
  if (title.includes("चालीसा") || title.includes("स्तोत्र") || title.includes("पाठ")) return topicIconClassMap.stotra;
  if (title.includes("मंत्र") || title.includes("जाप")) return topicIconClassMap.japa;
  if (title.includes("ध्यान")) return topicIconClassMap.dhyan;
  if (title.includes("मंदिर") || title.includes("दर्शन")) return topicIconClassMap.mandir;
  if (title.includes("गैलरी") || title.includes("चित्र")) return topicIconClassMap.gallery;
  return topicIconClassMap.default;
}

function renderBlock(block) {
  if (block.type === "panchang-live") {
    return `
      <article class="detail-panel">
        <h3 class="panel-title">${iconHtmlByClass(topicIconClassMap.panchang)}<span>लाइव पंचांग चित्रकूट</span></h3>
        <div id="panchang-live-container" class="info-body">
          <p>डेटा लोड हो रहा है...</p>
        </div>
      </article>
    `;
  }
  if (block.type === "counter") {
    return `
      <div class="japa-container">
        <div id="japaCountDisplay" class="japa-display">0</div>
        <div class="japa-meta">माला: <span id="malaCountDisplay">0</span> (108 का एक चक्र)</div>
        <button id="btnJapaTap" class="japa-tap-zone">राम</button>
        <div class="japa-actions">
          <button id="btnJapaReset" class="reset-btn">रीसेट (Reset)</button>
        </div>
      </div>
    `;
  }

  const title = block.title || "";
  const text = block.text || "";
  const items = block.items || [];

  const isStotra = text && (text.includes("\n") || title.includes("पाठ") || title.includes("आरती") || title.includes("चालीसा") || title.includes("स्तोत्र"));
  const isGallery = items.length > 0 && items.some(i => i && typeof i === "object" && i.image);
  const isLongList = items.length > 0 && items.some(i => typeof i === "object" && i.text && i.text.length > 60);

  let contentClass = isStotra ? "stotra-body" : (isGallery ? "gallery-body" : "info-body");
  if (isLongList) contentClass += " description-list";

  const panelClasses = ["detail-panel"];
  if (isStotra) panelClasses.push("panel-stotra");
  if (isGallery) panelClasses.push("panel-gallery");
  if (block.type) panelClasses.push(`panel-${block.type}`);

  let html = `<article class="${panelClasses.join(" ")}">${title ? `<h3 class="panel-title">${iconHtmlByClass(blockIconClass(block))}<span>${displayTitle(title)}</span></h3>` : ""}`;

  if (text) {
    const formattedText = text.replace(/\n/g, "<br>");
    html += `<div class="${contentClass}"><p>${formattedText}</p></div>`;
  }

  if (items.length > 0) {
    const EMOJI_HIDE_SECTIONS = new Set(["kali-upasana","shiv-upasana","das-mahavidya","yogini","nitya-puja","sadhana","stotra-aarti"]);
    const hideEmojis = EMOJI_HIDE_SECTIONS.has(currentSectionId);
    const listItems = items.map(item => {
      if (!item) return "";
      if (typeof item === "object") {
        const itemText = cleanItemText(item.text || "");
        if (item.image) return `<li class="photo-card"><img src="${item.image}" loading="lazy" alt="${itemText}"><small>${itemText}</small></li>`;
        if (item.logo) return `<li class="logo-item"><button class="logo-link" data-url="${item.url}"><img src="${item.logo}" alt=""><span>${itemText}</span></button></li>`;

        let iconHtml = "";
        if (!hideEmojis) iconHtml = getIconHtml(item.icon || item.symbol || leadingSymbol(item.text) || blockIconClass(block));
        if (item.pdfUrl) return `<li><button class="item-link" data-pdf="${item.pdfUrl}">${iconHtml}<span>${itemText}</span></button></li>`;
        if (item.url) return `<li><button class="item-link" data-url="${item.url}">${iconHtml}<span>${itemText}</span></button></li>`;
        if (item.link) return `<li><button class="item-link" data-section="${item.link}">${iconHtml}<span>${itemText}</span></button></li>`;
        return `<li><div class="info-item">${iconHtml}<span>${itemText}</span></div></li>`;
      }
      const itemText = cleanItemText(item);
      const blockIconHtml = hideEmojis ? "" : iconHtmlByClass(blockIconClass(block));
      return `<li><div class="info-item">${blockIconHtml}<span>${itemText}</span></div></li>`;
    }).join("");
    html += `<ul class="${contentClass}">${listItems}</ul>`;
  }

  html += `</article>`;
  return html;
}

document.addEventListener("click", (e) => {
  const themeBtn = e.target.closest("#navTheme");
  if (themeBtn) return toggleTheme();
  const sectionBtn = e.target.closest("[data-section]");
  if (sectionBtn) return window.showSection(sectionBtn.dataset.section);
  const categoryBtn = e.target.closest("[data-category]");
  if (categoryBtn) return showCategoryGroup(categoryBtn.dataset.category);
  const pdfBtn = e.target.closest("[data-pdf]");
  if (pdfBtn) return window.open(pdfBtn.dataset.pdf, '_system');
  const urlBtn = e.target.closest("[data-url]");
  if (urlBtn) return window.open(urlBtn.dataset.url, '_system');
});

function updateHistory(state) { history.pushState(state, "", ""); }

window.addEventListener("popstate", (e) => {
  isRestoringHistory = true;
  const s = e.state || { view: "home" };
  if (s.view === "section") window.showSection(s.sectionId);
  else if (s.view === "categories") showCategories();
  else showHome();
  isRestoringHistory = false;
});

async function initPanchang() {
  const container = document.querySelector("#panchang-live-container");
  if (!container) return;

  try {
    const now = new Date();
    // Fetch Sunset/Sunrise from Aladhan (Reliable & Free)
    const sunResp = await fetch(`https://api.aladhan.com/v1/timingsByAddress?address=Chitrakoot,UP,India`);
    const sunData = await sunResp.json();
    const timings = sunData.data.timings;

    container.innerHTML = `
      <div class="panchang-data">
        <p><b>दिनांक:</b> ${now.toLocaleDateString('hi-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
        <p><b>सूर्योदय:</b> ${timings.Sunrise}</p>
        <p><b>सूर्यास्त:</b> ${timings.Sunset}</p>
        <p><b>चंद्रोदय:</b> ${timings.Moonrise}</p>
        <hr>
        <p style="font-size: 0.9em; color: #666;">नोट: तिथि और नक्षत्र की गणना प्रक्रियाधीन है।</p>
      </div>
    `;
  } catch (e) {
    container.innerHTML = "<p>नेटवर्क त्रुटि। कृपया इंटरनेट कनेक्शन जांचें।</p>";
  }
}

async function scheduleNotification(title, body, hour, minute) {
  const Notifs = window.Capacitor?.Plugins?.LocalNotifications;
  if (!Notifs) {
    alert("यह फीचर केवल मोबाइल ऐप पर उपलब्ध है।");
    return;
  }

  const perm = await Notifs.requestPermissions();
  if (perm.display !== 'granted') {
    alert("कृपया नोटिफिकेशन की अनुमति दें।");
    return;
  }

  await Notifs.schedule({
    notifications: [{
      title, body, id: hour + minute,
      schedule: { on: { hour, minute }, repeats: true },
      sound: 'beep.wav'
    }]
  });
  alert(`सफलतापूर्वक ${hour}:${minute} के लिए रिमाइंडर सेट किया गया।`);
}

document.addEventListener("DOMContentLoaded", () => {
  const searchInput = document.querySelector("#searchInput");
  if (searchInput) {
    let searchTimeout;
    searchInput.oninput = (e) => {
      currentQuery = e.target.value;
      clearTimeout(searchTimeout);
      searchTimeout = setTimeout(() => {
        renderMenu();
      }, 300); // 300ms debounce
    };
  }
  if (navHome) navHome.onclick = showHome;
  if (navCategories) navCategories.onclick = showCategories;
  if (navTheme) navTheme.onclick = (event) => {
    event.preventDefault();
    event.stopPropagation();
    toggleTheme();
  };

  const btnIncrease = document.querySelector("#btnTextIncrease");
  const btnDecrease = document.querySelector("#btnTextDecrease");
  if (btnIncrease) btnIncrease.onclick = () => { if (currentFontSize < 2.5) { currentFontSize += 0.1; applyFontSize(); } };
  if (btnDecrease) btnDecrease.onclick = () => { if (currentFontSize > 0.8) { currentFontSize -= 0.1; applyFontSize(); } };

  const btnShare = document.querySelector("#btnShare");
  if (btnShare) btnShare.onclick = () => {
    const sId = history.state?.sectionId;
    if (!sId) return;
    const s = sectionById(sId);
    if (!s) return;
    const shareText = `*${s.title}*\n\n${introForSection(s) || s.desc || ""}\n\nदर्शन के लिए शिवकाली ऐप डाउनलोड करें। 🚩`;
    const waUrl = `https://wa.me/?text=${encodeURIComponent(shareText)}`;
    window.open(waUrl, '_system');
  };

  renderMenu();
  if (!history.state) history.replaceState({ view: "home" }, "", "");
});

document.addEventListener("deviceready", () => {
  const app = window.Capacitor?.Plugins?.App;
  if (app) app.addListener("backButton", () => {
    if (history.state && history.state.view !== "home") window.history.back();
    else app.exitApp();
  });
});
